  'table-daily-limits-free' => 'Անվճար գործիքները սահմանափակում են միաձուլումների քանակը, որոնք կարող եք կատարել ամեն օր առանց վճարման:',
  'table-daily-limits-paid' => 'Վճարովի գործիքները ցանկացած պահի թույլ են տալիս անսահմանափակ միաձուլումներ՝ առանց ամենօրյա սահմանափակումների կամ օգտագործման սահմանափակումների:',
  'table-file-count' => 'Ֆայլերի առավելագույն քանակը',
  'table-file-count-free' => 'Անվճար տարբերակները հաճախ սահմանափակում են, թե քանի ֆայլ կարող եք միավորել մեկ նստաշրջանում կամ խմբաքանակ վերբեռնել:',
  'table-file-count-paid' => 'Վճարովի տարբերակներն աջակցում են բազմաթիվ ֆայլերի միանգամից միաձուլմանը` ֆայլերի քանակի ավելի բարձր կամ առանց սահմանափակումների:',
  'table-speed' => 'Արագություն',
  'table-speed-free' => 'Անվճար գործիքները կարող են ավելի դանդաղ մշակել միաձուլումը, երբ սերվերները սպառողների մեծ պահանջարկ ունեն պիկ ժամանակներում:',
  'table-speed-paid' => 'Վճարովի գործիքները սովորաբար ապահովում են ավելի արագ միաձուլման կատարում՝ առաջնահերթ մշակման և ավելի լավ ռեսուրսների հետ:',
  'table-watermark' => 'Ջրի նշագծի հետ կապված խնդիրներ',
  'table-watermark-free' => 'Որոշ անվճար միաձուլումներ միացված ֆայլերի վրա տեղադրում են ջրանիշներ, որոնք օգտվողները կարող են շեղող կամ ոչ պրոֆեսիոնալ համարել:',
  'table-watermark-paid' => 'Վճարովի միաձուլումները ստեղծում են մաքուր միաձուլված PDF-ներ՝ առանց ջրանիշների և առաջարկում են պրոֆեսիոնալ որակի արդյունք:',
  'common-problems-heading' => 'Ընդհանուր խնդիրներ և արագ շտկումներ',
  'common-problems-intro' => 'Օգտատերերը կարող են խնդիրներ ունենալ PDF միաձուլման ժամանակ: Ահա մի քանի ընդհանուր օրինակներ և ինչպես դրանք լուծել:',
  'problem1-heading' => 'Ֆայլերը չեն վերբեռնվում',
  'problem1-para' => 'Ֆայլերը կարող են չվերբեռնվել դանդաղ ինտերնետի կամ չաջակցվող ձևաչափերի պատճառով: Ստուգեք ֆայլի տեսակը և ապահովեք կայուն ինտերնետային կապ, նախքան նորից փորձելը: Անհրաժեշտության դեպքում սեղմեք շատ մեծ ֆայլեր՝ գործիքի վերբեռնման սահմանափակումները բավարարելու համար:',
  'problem2-heading' => 'Էջերի սխալ դասավորություն',
  'problem2-para' => 'Միաձուլվելուց հետո էջերը կարող են հայտնվել սխալ հաջորդականությամբ: Նախքան միաձուլումն ավարտելը, ձեռքով վերադասավորեք էջերը՝ օգտագործելով նախադիտման հնարավորությունը: Զգուշորեն հաստատեք հաջորդականությունը՝ վերջնական PDF-ում սխալներից խուսափելու համար:',
  'problem3-heading' => 'Չմիաձուլվող խոշոր ֆայլեր',
  'problem3-para' => 'Շատ մեծ PDF ֆայլերը կարող են չմիավորվել գործիքի սահմանափակումների պատճառով: Ֆայլերը բաժանեք փոքր մասերի և հաջորդաբար միացրեք դրանք: Որոշ գործիքներ առաջարկում են պրեմիում տարբերակ՝ մեծ ֆայլերի չափսերը արդյունավետ կերպով կարգավորելու համար:',
  'problem4-heading' => 'Միաձուլումից հետո աղոտ պատկերներ',
  'problem4-para' => 'Միաձուլված PDF ֆայլերը կարող են ցույց տալ մշուշոտ պատկերներ, եթե լուծաչափը ցածր է: Ընտրեք բարձրորակ արդյունք կամ խուսափեք պատկերների չափից ավելի սեղմումից: Միշտ նախադիտեք միավորված PDF-ը՝ պատկերի հստակությունը ստուգելու համար:',
  'conclusion-heading' => 'Եզրակացություն. 2026 թվականին PDF ֆայլերը համատեղելու լավագույն միջոցը',
  'conclusion-para1' => 'PDF-ի միաձուլումը կարևոր է դարձել ժամանակակից թվային աշխատանքային հոսքերում, քանի որ թիմերը ամեն օր մշակում են բազմաթիվ փաստաթղթեր: Պայմանագրերի, հաշվետվությունների և ձևաթղթերի համադրումը մեկ PDF ֆայլերում բարելավում է պարզությունը, կազմակերպվածությունը և արտադրողականությունը ձեռնարկություններում, դպրոցներում և հեռավոր աշխատանքում: Միաձուլված PDF-ները պահպանում են ձևաչափումը, թույլ են տալիս էջերի վերադասավորում և պարզեցնում էջերի ավելացումն ու հեռացումը:',
  'conclusion-para2' => 'Հանրաճանաչ գործիքները, ինչպիսիք են Smallpdf-ը, iLovePDF-ը, Adobe Acrobat-ը և PDFgear-ը, ապահովում են հուսալի միաձուլում տարբեր հնարավորությունների հետ, այդ թվում՝ քաշել և թողնել միջերեսները, անվտանգ վերբեռնումները և միջպլատֆորմային աջակցությունը: Անվճար գործիքները հաճախ սահմանափակումներ ունեն ֆայլի չափի, ամենօրյա միաձուլումների և ջրանիշների վրա, մինչդեռ վճարովի տարբերակներն առաջարկում են ավելի արագ մշակում և անսահմանափակ միաձուլումներ:',
  'conclusion-para3' => 'Ընդլայնված խորհուրդները ներառում են միաձուլման ժամանակ ֆայլերի սեղմումը, էջանիշերի ավելացումը, սկանավորված և թվային PDF-ների համադրումը և ֆայլերը գաղտնաբառերով ապահովելը:',
  'faqs-heading' => 'ՀՏՀ-ներ',
  'faq1-question' => 'Ո՞րն է PDF-ի լավագույն անվճար միաձուլումը:',
  'faq1-answer' => 'Smallpdf-ը և iLovePDF-ը PDF-ի լավագույն անվճար միաձուլումներից են՝ հեշտ առցանց հասանելիությամբ: Երկու գործիքներն էլ թույլ են տալիս արագ միաձուլել ֆայլերը՝ առանց տեղադրման կամ ծախսերի:',
  'faq2-question' => 'Կարո՞ղ եմ միաձուլել անսահմանափակ PDF ֆայլեր:',
  'faq2-answer' => 'Անվճար գործիքները հաճախ սահմանափակում են PDF ֆայլերի քանակը, որոնք կարող եք միաձուլել ամեն օր: Վճարովի PDF միաձուլումները թույլ են տալիս անսահմանափակ միաձուլումներ առանց սահմանափակումների կամ ամենօրյա սահմանափակումների:',
  'faq3-question' => 'Ինչպե՞ս միաձուլել մեծ PDF ֆայլերը առանց սխալների:',
  'faq3-answer' => 'Շատ մեծ PDF ֆայլերը միաձուլելուց առաջ բաժանեք փոքր հատվածների: Պրեմիում գործիքների օգտագործումն օգնում է ավելի արդյունավետ կարգավորել ավելի մեծ ֆայլերը:',
  'faq4-question' => 'Արդյո՞ք PDF-ների միաձուլումը նվազեցնում է որակը:',
  'faq4-answer' => 'PDF-ների միաձուլումը սովորաբար պահպանում է տեքստի և դասավորության որակը: Չափազանց սեղմումը կամ ցածր լուծաչափի կարգավորումները կարող են նվազեցնել պատկերի հստակությունը:',
  'faq5-question' => 'Արդյո՞ք առցանց PDF միաձուլումները անվտանգ են:',
  'faq5-answer' => 'Հեղինակավոր առցանց PDF միաձուլումները օգտագործում են գաղտնագրում, որպեսզի ապահովեն վերբեռնումները: Խուսափեք անվստահելի կայքերից՝ տվյալների հնարավոր խախտումները կանխելու համար:',
  'titl' => 'Ինչպես հեշտությամբ միաձուլել PDF ֆայլերը 2026 թվականին | Անվճար և վճարովի',
  'descriptions' => 'Իմացեք, թե ինչպես հեշտությամբ միացնել PDF ֆայլերը՝ օգտագործելով լավագույն անվճար և վճարովի գործիքները: Ներառում է քայլ առ քայլ ուղեցույցներ, պրոֆեսիոնալ խորհուրդներ և ընդհանուր խնդիրների լուծումներ: Կարդալ ավելին!',
);
